import { bar } from 'axylo';

/**
 * Sort key for a quarter written as "YYYY Qn" (e.g. "2025 Q3").
 * Quarters are categories in Axylo 1.0, and categories keep the order in which
 * they first appear, so the rows must be put in calendar order before charting.
 * Labels that do not match sort after the ones that do, in their original order.
 */
function quarterKey(label) {
  const match = /^\s*(\d{4})\s*Q([1-4])\s*$/i.exec(String(label));
  return match ? Number(match[1]) * 4 + Number(match[2]) : Number.POSITIVE_INFINITY;
}

/** The options for the chart, shared by `render` and by `validate()` checks in Node. */
export function chartOptions(data) {
  // Copy before sorting: the caller's rows are never changed. Array#sort is stable.
  const rows = [...data].sort((a, b) => quarterKey(a.quarter) - quarterKey(b.quarter));

  return {
    title: 'Quarterly sales by region',
    data: rows,
    // Quarters are categories with a natural order, so their labels may be thinned if they do not fit.
    x: { field: 'quarter', type: 'category', ordered: true },
    // Wide rows: one field per region, grouped side by side. The values arrive as decimal strings.
    y: [
      { field: 'north', label: 'North', parse: 'number' },
      { field: 'central', label: 'Central', parse: 'number' },
      { field: 'west', label: 'West', parse: 'number' },
    ],
    layout: 'grouped',
    // With several y fields the shared value axis is titled by the `value` message ("Value" by default).
    messages: { value: 'Sales' },
  };
}

/**
 * Draw the chart into `element` and return the Axylo chart handle.
 * @param {HTMLElement} element the chart container
 * @param {Array<{quarter: string, north: string, central: string, west: string}>} data rows from data.json
 */
export default function render(element, data) {
  return bar(element, chartOptions(data));
}

