input.command:
node --conditions=development --input-type=module -e "
import { readFileSync } from 'node:fs';
import { validate } from 'axylo';
import render, { chartOptions } from './chart.js';
const data = JSON.parse(readFileSync('data.json', 'utf8'));
const before = JSON.stringify(data);
const opts = chartOptions(data);
console.log('typeof render:', typeof render, '| arity:', render.length);
console.log('order:', opts.data.map(r => r.quarter).join(', '));
console.log('input unchanged:', JSON.stringify(data) === before);
const problems = validate('bar', opts);
console.log('diagnostics:', problems.length);
for (const d of problems) console.log(' ', d.code, d.level, d.message);
"

