node --conditions=development --input-type=module -e "
import { readFileSync } from 'node:fs';
import { validate } from 'axylo';
import { chartOptions } from './chart.js';
const opts = chartOptions(JSON.parse(readFileSync('data.json', 'utf8')));
const noParse = { ...opts, y: opts.y.map(({ parse, ...f }) => f) };
const typo = { ...opts, y: [{ ...opts.y[0], field: 'nort' }, ...opts.y.slice(1)] };
for (const [name, o] of [['no parse', noParse], ['typo', typo]])
  console.log(name, '->', validate('bar', o).map(d => d.code + ' ' + d.level).join(', ') || 'none');
"

